function namaKunci_(s) { return teks_(s).toLowerCase().replace(/[^a-z ]/g, ' ').replace(/\s+/g, ' ').trim(); }

/** Membaca database sertifikat. Tab yang namanya memuat "LKMM" = database LKMM; tab lain yang punya kolom Nama dan NIM = database PWI. */
