    for (var r = 0; r < Math.min(6, isi.length) && kN < 0; r++) {
      var bn = -1, bi = -1;
      isi[r].forEach(function (v, i) { var t = teks_(v).toLowerCase(); if (bn < 0 && /^nama\b/.test(t)) bn = i; if (bi < 0 && /^(nim|n\.?i\.?m\.?)$/.test(t)) bi = i; });
